 package com.papazone.notification;  import jakarta.persistence.*; import java.time.LocalDateTime;  @Entity @Table(         name = "email_notifications",         uniqueConstraints = {                 @UniqueConstraint(                         name = "uk_email_notification_order_event",                         columnNames = {"order_id", "event_type"}                 )         } ) public class Notification {      @Id     @GeneratedValue(strategy = GenerationType.IDENTITY)     private Long id;      @Column(name = "order_id", nullable = false)     private Long orderId;      @Column(name = "customer_id", nullable = false)     private Long customerId;      @Column(name = "tracking_code")     private String trackingCode;      @Column(name = "event_type", nullable = false, length = 50)     private String eventType;      @Column(nullable = false, length = 20)     private String status;      @Column(name = "attempt_count", nullable = false)     private int attemptCount = 0;      @Column(name = "next_retry_at")     private LocalDateTime nextRetryAt;      @Column(name = "last_error", length = 2000)     private String lastError;      @Column(name = "created_at", nullable = false)     private LocalDateTime createdAt;      @Column(name = "updated_at", nullable = false)     private LocalDateTime updatedAt;      @Column(name = "sent_at")     private LocalDateTime sentAt;      @PrePersist     public void onCreate() {         LocalDateTime now = LocalDateTime.now();         createdAt = now;         updatedAt = now;          if (status == null) {             status = "PENDING";         }     }      @PreUpdate     public void onUpdate() {         updatedAt = LocalDateTime.now();     }      public Long getId() { return id; }     public Long getOrderId() { return orderId; }     public void setOrderId(Long orderId) { this.orderId = orderId; }      public Long getCustomerId() { return customerId; }     public void setCustomerId(Long customerId) { this.customerId = customerId; }      public String getTrackingCode() { return trackingCode; }     public void setTrackingCode(String trackingCode) { this.trackingCode = trackingCode; }      public String getEventType() { return eventType; }     public void setEventType(String eventType) { this.eventType = eventType; }      public String getStatus() { return status; }     public void setStatus(String status) { this.status = status; }      public int getAttemptCount() { return attemptCount; }     public void setAttemptCount(int attemptCount) { this.attemptCount = attemptCount; }      public LocalDateTime getNextRetryAt() { return nextRetryAt; }     public void setNextRetryAt(LocalDateTime nextRetryAt) { this.nextRetryAt = nextRetryAt; }      public String getLastError() { return lastError; }     public void setLastError(String lastError) { this.lastError = lastError; }      public LocalDateTime getCreatedAt() { return createdAt; }     public LocalDateTime getUpdatedAt() { return updatedAt; }      public LocalDateTime getSentAt() { return sentAt; }     public void setSentAt(LocalDateTime sentAt) { this.sentAt = sentAt; }  }